// src/components/HowToSignUp.js
import React, { useState } from 'react';

const HowToSignUp = () => {
  const [selectedType, setSelectedType] = useState(null);
  const [gearChecklist, setGearChecklist] = useState({
    swim: false,
    bike: false,
    run: false,
    nutrition: false
  });
  const [quizScore, setQuizScore] = useState(0);
  const [progress, setProgress] = useState(0);

  const handleTypeSelect = (type) => {
    setSelectedType(type);
    setProgress(progress + 25);  // Increment progress by 25% on type selection
  };

  const handleChecklistChange = (item) => {
    setGearChecklist({ ...gearChecklist, [item]: !gearChecklist[item] });
    if (!gearChecklist[item]) setProgress(progress + 10);  // Increment progress by 10% on checklist completion
  };

  const handleQuizAnswer = (isCorrect) => {
    if (isCorrect) setQuizScore(quizScore + 1);
    setProgress(progress + 15);  // Increment progress with each quiz answer
  };

  const renderRaceTips = () => {
    switch (selectedType) {
      case "Sprint":
        return "Focus on short training sessions, aim for balanced practice across swim, bike, and run.";
      case "Olympic":
        return "Train for endurance. Plan weekly for moderate sessions across swim, bike, and run.";
      case "Half Ironman":
        return "Requires strong endurance. Practice long-distance, steady pace, and focus on nutrition.";
      case "Ironman":
        return "Intensive training required. Consider a coach, and optimize for endurance, nutrition, and recovery.";
      default:
        return "Select a race type to see specific tips and requirements.";
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>How to Sign Up for a Triathlon</h1>

      <div className="progress-tracker">
        <div className="progress-circle">
          <div className="progress" style={{ strokeDashoffset: `calc(100 - ${progress})` }}></div>
          <div className="progress-text">{progress}%</div>
        </div>
        <p>Complete each section to reach 100% readiness!</p>
      </div>

      <h2>1. Choose Your Triathlon Type</h2>
      <p>Select a race type to see customized tips:</p>
      <div className="race-selector">
        {["Sprint", "Olympic", "Half Ironman", "Ironman"].map((type) => (
          <div
            key={type}
            className={`race-card ${selectedType === type ? 'selected' : ''}`}
            onClick={() => handleTypeSelect(type)}
          >
            <h3>{type}</h3>
            {selectedType === type && (
              <p className="race-details">{renderRaceTips()}</p>
            )}
          </div>
        ))}
      </div>

      <h2>2. Register for the Event</h2>
      <p>
        Visit <a href="https://www.active.com" target="_blank" rel="noopener noreferrer">Active.com</a> or <a href="https://www.ironman.com" target="_blank" rel="noopener noreferrer">Ironman</a> to find and register for events. Be sure to register early!
      </p>

      <h2>3. Gear Checklist</h2>
      <p>Check off each item as you prepare:</p>
      <ul>
        {Object.keys(gearChecklist).map((item) => (
          <li key={item} onClick={() => handleChecklistChange(item)}>
            <input
              type="checkbox"
              checked={gearChecklist[item]}
              onChange={() => handleChecklistChange(item)}
            />
            <span className={gearChecklist[item] ? "checked-item" : ""}>{item}</span>
          </li>
        ))}
      </ul>

      <h2>4. Preparing for Race Day</h2>
      <p>Plan for each stage and ensure your gear and nutrition are ready:</p>
      <p><strong>Your Plan:</strong> Based on your race type, here’s a suggested timeline:</p>
      {selectedType && (
        <div className="training-plan">
          <p>{selectedType} Training Plan</p>
          <ul>
            {selectedType === "Sprint" && <li>Focus on balance between swim, bike, and run - 8 weeks of training recommended.</li>}
            {selectedType === "Olympic" && <li>Increase endurance and train 3-4 times a week - 12 weeks of training recommended.</li>}
            {selectedType === "Half Ironman" && <li>Endurance and pacing are key - 16 weeks of training with steady progress.</li>}
            {selectedType === "Ironman" && <li>Dedicated training with long-distance sessions - 24+ weeks recommended.</li>}
          </ul>
        </div>
      )}

      <h2>5. FAQs</h2>
      <div className="faq-section">
        <details>
          <summary>What should I wear during a triathlon?</summary>
          <p>A tri-suit is recommended for smooth transitions between each stage.</p>
        </details>
        <details>
          <summary>Can beginners attempt an Ironman?</summary>
          <p>It's possible, but extensive training is necessary. Consult a coach for best results.</p>
        </details>
        <details>
          <summary>How should I fuel during the race?</summary>
          <p>For longer races, plan to refuel every 45-60 minutes with electrolytes and light snacks.</p>
        </details>
      </div>

      <h2>6. Mini Quiz</h2>
      <p>Test your knowledge!</p>
      <div className="quiz-section">
        <p>1. Which triathlon type is best for beginners?</p>
        {["Sprint", "Olympic", "Half Ironman", "Ironman"].map((type) => (
          <button
            key={type}
            onClick={() => handleQuizAnswer(type === "Sprint")}
          >
            {type}
          </button>
        ))}
        <p>Your score: {quizScore}/1</p>
      </div>

      <style>
        {`
          .progress-tracker { text-align: center; margin-bottom: 20px; }
          .progress-circle { width: 80px; height: 80px; border-radius: 50%; display: inline-block; background: #eee; position: relative; }
          .progress { stroke-dasharray: 100; stroke-dashoffset: 100; transition: stroke-dashoffset 0.4s ease; stroke-width: 5; }
          .progress-text { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 18px; }
          .race-selector { display: flex; gap: 15px; margin: 20px 0; }
          .race-card { border: 1px solid #ccc; padding: 15px; border-radius: 8px; cursor: pointer; transition: transform 0.3s; }
          .race-card.selected { background: #e0f7fa; transform: scale(1.05); }
          .training-plan { margin-top: 10px; padding: 10px; border: 1px solid #ddd; background-color: #f9f9f9; }
          .faq-section details { margin-top: 10px; }
          .quiz-section { margin-top: 15px; }
          .quiz-section button { margin: 5px; padding: 8px 15px; cursor: pointer; }
          .checked-item { color: green; text-decoration: line-through; }
        `}
      </style>
    </div>
  );
};

export default HowToSignUp;
